/* @lc app=leetcode id=2050 lang=kotlin */
class Solution { fun minimumTime(n: Int, relations: Array<IntArray>, time: IntArray): Int = IntArray(n).let { inDeg -> Array(n) { mutableListOf<Int>() }.apply { relations.forEach { r -> this[r[0] - 1].add(r[1] - 1).run { inDeg[r[1] - 1]++ } } }.let { adj -> IntArray(n).let { dist -> java.util.ArrayDeque<Int>().apply { (0 until n).forEach { i -> if (inDeg[i] == 0) { add(i).run { dist[i] = time[i] } } } }.let { q -> generateSequence { q.poll() }.forEach { u -> adj[u].forEach { v -> maxOf(dist[v], dist[u] + time[v]).let { dist[v] = it }.run { if (--inDeg[v] == 0) q.add(v) } } }.run { dist.maxOrNull() ?: 0 } } } } }